import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

// Generated by tool/make_sounds.py. The number is how many copies of the
// sound can play at once: sounds that repeat quickly get several players, so
// a second "correct" or "tick" overlaps the first instead of cutting it off.
const sources = {
  tap: [require('../assets/sounds/tap.wav'), 3],
  open: [require('../assets/sounds/open.wav'), 2],
  close: [require('../assets/sounds/close.wav'), 2],
  save: [require('../assets/sounds/save.wav'), 1],
  countdown: [require('../assets/sounds/countdown.wav'), 2],
  go: [require('../assets/sounds/go.wav'), 1],
  correct: [require('../assets/sounds/correct.wav'), 3],
  pass: [require('../assets/sounds/pass.wav'), 3],
  tick: [require('../assets/sounds/tick.wav'), 2],
  timesup: [require('../assets/sounds/timesup.wav'), 1],
  fanfare: [require('../assets/sounds/fanfare.wav'), 1],
} as const;

export type SoundName = keyof typeof sources;

type Pool = { players: AudioPlayer[]; next: number };

const pools = new Map<SoundName, Pool>();
let enabled = true;
let ready = false;

/** Loads every sound once at startup. Safe to call more than once. */
export function initSounds(): void {
  if (ready) return;
  ready = true;
  // A party game should be heard even with the ringer switch on silent;
  // the in-app Sound toggle turns it off. Mix with any music playing.
  setAudioModeAsync({ playsInSilentMode: true, interruptionMode: 'mixWithOthers' }).catch(
    () => {},
  );
  for (const [name, [source, copies]] of Object.entries(sources) as [
    SoundName,
    readonly [number, number],
  ][]) {
    const players: AudioPlayer[] = [];
    for (let i = 0; i < copies; i++) {
      try {
        const player = createAudioPlayer(source);
        player.volume = 1;
        players.push(player);
      } catch {
        // Audio unavailable (e.g. some test environments): stay silent.
      }
    }
    if (players.length) pools.set(name, { players, next: 0 });
  }
}

export function setSoundEnabled(on: boolean): void {
  enabled = on;
}

/** Picks an idle player, or the one that has been playing longest. */
function pick(pool: Pool): AudioPlayer {
  const n = pool.players.length;
  for (let k = 0; k < n; k++) {
    const i = (pool.next + k) % n;
    if (!pool.players[i].playing) {
      pool.next = (i + 1) % n;
      return pool.players[i];
    }
  }
  const player = pool.players[pool.next];
  pool.next = (pool.next + 1) % n;
  return player;
}

/** Plays a sound from the start. Never throws. */
export function play(name: SoundName): void {
  if (!enabled) return;
  const pool = pools.get(name);
  if (!pool) return;
  const player = pick(pool);
  try {
    if (!player.playing && player.currentTime === 0) {
      player.play();
      return;
    }
    // A finished or busy player sits past the start: rewind first, and only
    // play once the seek has landed (playing straight away can be dropped).
    if (player.playing) player.pause();
    player
      .seekTo(0)
      .then(() => player.play())
      .catch(() => {});
  } catch {
    // Never let a sound failure interrupt the game.
  }
}
